background.css:
background: linear-gradient(180deg, rgba(43,34,24,0.78) 0%, rgba(35,26,18,0.82) 100%);
border-top: 1px solid rgba(192,148,88,0.35);
box-shadow:
  inset 0 0 40px rgba(15,10,5,0.55),
  inset 0 1px 0 rgba(255,208,140,0.08);

background: linear-gradient(180deg, rgba(8,12,22,0.9) 0%, rgba(14,20,34,0.92) 100%);
border-top: 1px solid rgba(120,180,255,0.55);
box-shadow:
  inset 0 1px 0 rgba(120,180,255,0.25),
  0 0 24px rgba(120,180,255,0.18);

background: linear-gradient(180deg, rgba(90,62,48,0.72) 0%, rgba(70,46,34,0.78) 100%);
border-radius: 20px 20px 0 0;
box-shadow:
  0 -4px 18px rgba(60,40,30,0.25),
  inset 0 1px 0 rgba(255,245,230,0.1);
